(* [comment removed for export] *)
Definition DGM_CELLS : list (Z * Z * Z) := [(1338840, 1, 1); (1308456, 8, 1208368); (1335544, 8, 2147450880)].
(* [comment removed for export] *)
Definition Wfw (S a : Z) : Prop := S - 2320 <= a < S \/ 1319128 <= a < 1319144 \/ 1319152 <= a < 1319168 \/ 1319176 <= a < 1319184 \/ 1319256 <= a < 1319260.
(* [comment removed for export] *)
Definition stderrMA (MV : word -> option byte) : Prop :=
  rdn ASEGS MV (Z_to_bv 64 1319160) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 6924696)) /\ rdn ASEGS MV (Z_to_bv 64 1319176) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 6924696))
  /\ rdn ASEGS MV (Z_to_bv 64 1319128) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0)) /\ rdn ASEGS MV (Z_to_bv 64 1319136) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0)).

Section FPX_1. Context {fx : PropExec.FPState}.
Variable scfg : SpuriousCfg.
Section Fwrite.
  Variable L : asan_layout.
  Variable ar : asan_run.
  Variable C : asan_statics_cells.
  Variable IL : icpt_layout.
  Variable HI : asan_iface.
  Hypothesis HIok : asan_iface_okB L ar C scfg HI.
  Hypothesis ICok : aicpt_ok L ar IL scfg HI.
  Hypothesis ILY : as0_icpt_layout IL.
  Variable sp0 : word.
  Hypothesis Hsp : 0x7fff80000000 <= bv_unsigned sp0 <= 2 ^ 47.
  Hypothesis Hal : bv_unsigned sp0 mod 16 = 0.
  Hypothesis DL : drv_layoutA L ar IL sp0.
  Hypothesis Hdgm : incl DGM_CELLS (asc_cells C).
  Variable M0 : word -> option byte.
  #[local] Notation dinvA := (dinv ar HI sp0 M0).
  #[local] Notation usp := (bv_unsigned sp0).
  #[local] Notation rom := (seg_rom ASEGS).

  #[using="scfg L C IL HIok Hsp DL Hdgm"] Lemma dgm_cell_vis : forall LB LK cr A M (model : Model) a n v, dinvA LB LK cr A M model -> In (a, n, v) DGM_CELLS ->
    rdn ASEGS (mrestrict (ahid A model) M) (Z_to_bv 64 a) (Z.to_nat n) = Some (word_to_le_bytes (Z.to_nat n) (Z_to_bv 64 v)).
